"use strict";(self.webpackChunkfaurum=self.webpackChunkfaurum||[]).push([[916],{5434:(e,i,n)=>{n.d(i,{w:()=>g});const a=n.p+"static/media/xjvowzctum_1.2357f25044295e9eda73.webp",t=n.p+"static/media/xjvowzctum_2.8c05450383bf0313e7b9.webp",r=n.p+"static/media/bnrleqdyha_1.5f10e0b891a525ee99c3.webp",o=n.p+"static/media/bnrleqdyha_2.20155bba7b77250790dc.webp",s=n.p+"static/media/bnrleqdyha_3.ccee80f4c18c362e655e.webp",d=n.p+"static/media/pkmsvzutgf_1.a6f8bd7d697892f9140a.webp",h=n.p+"static/media/qwoeijxhcd_1.9c2255c1b99fa8091be5.webp",u=n.p+"static/media/qwoeijxhcd_2.32bfa2c882cb0e334aa5.webp",l=n.p+"static/media/qwoeijxhcd_3.6a2dd0d214c81e6ac1a4.webp",m=n.p+"static/media/qwoeijxhcd_5.1e4a219605cb270add76.webp",c=n.p+"static/media/vwreifxhad_2.be48c2d1a2c681b536de.webp",g=[{id:"xjvowzctum",titleUA:"\u0424\u043e\u0440\u0443\u043c \u043c\u0438\u0440\u043e\u0442\u0432\u043e\u0440\u0446\u0456\u0432 \u0443 \u0412\u0456\u0434\u043d\u0456",titleEN:"Peacemakers Forum in Vienna",titleDE:"Peacemakers Forum in Wien",text1UA:"\u0412 \u0447\u0435\u0440\u0432\u043d\u0456 2024 \u0440\u043e\u043a\u0443 \u0443 \u0412\u0456\u0434\u043d\u0456 \u0432\u0456\u0434\u0431\u0443\u0432\u0441\u044f \u0424\u043e\u0440\u0443\u043c \u043c\u0438\u0440\u043e\u0442\u0432\u043e\u0440\u0446\u0456\u0432 - Peacekeepers Forum 2024 . \u0404\u0432\u0433\u0435\u043d \u0412\u043e\u043b\u0447\u0435\u043d\u043a\u043e, \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442 \u043f\u0441\u0438\u0445\u043e\u043b\u043e\u0433\u0456\u0447\u043d\u0438\u0445 \u043d\u0430\u0443\u043a,  \u0441\u043f\u0456\u0432\u0437\u0430\u0441\u043d\u043e\u0432\u043d\u0438\u043a \u043d\u0430\u0448\u043e\u0433\u043e \u0426\u0435\u043d\u0442\u0440\u0443, \u043b\u0456\u043a\u0430\u0440 \u0444\u0456\u0437\u0438\u0447\u043d\u043e\u0457 \u0442\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u043e\u0457 \u043c\u0435\u0434\u0438\u0446\u0438\u043d\u0438, \u0437\u0430\u0432\u0456\u0434\u0443\u0432\u0430\u0447 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u043c \u0432\u0456\u0434\u0434\u0456\u043b\u0435\u043d\u043d\u044f\u043c \u0426\u0435\u043d\u0442\u0440\u0443, \u043f\u0440\u0438\u0439\u043d\u044f\u0432 \u0432 \u043d\u044c\u043e\u043c\u0443 \u0443\u0447\u0430\u0441\u0442\u044c \u0437 \u0434\u043e\u043f\u043e\u0432\u0456\u0434\u0434\u044e  \u043d\u0430 \u0442\u0435\u043c\u0443: \u201c\u041f\u0441\u0438\u0445\u043e-\u0444\u0456\u0437\u0438\u0447\u043d\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u044f \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u0438\u0445 \u043f\u0456\u0434 \u0447\u0430\u0441 \u0432\u0456\u0439\u043d\u0438 \u0432 \u0423\u043a\u0440\u0430\u0457\u043d\u0456 , \u0441\u043e\u0446\u0456\u0430\u043b\u044c\u043d\u0438\u0439 \u0442\u0430 \u0456\u043d\u0434\u0438\u0432\u0456\u0434\u0443\u0430\u043b\u044c\u043d\u0438\u0439 \u0440\u0456\u0432\u043d\u0456 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u201d.",text1EN:"In June 2024, the Peacekeepers Forum 2024 was held in Vienna. Yevhen Volchenko, Candidate of Psychological Sciences, co-founder of our Center, doctor of physical and rehabilitation medicine, head of the rehabilitation department of the Center, took part in it with a report on the topic: \u201cPsycho-physical rehabilitation of military personnel during the war in Ukraine, social and individual levels of problems\u201d.",text1DE:"Im Juli 2024 haben Sie das Forum Militar - Peacekeepers Forum 2024 ver\xf6ffentlicht. \u0404\u0432\u0433\u0435\u043d \u0412\u043e\u043b\u0447\u0435\u043d\u043a\u043e, Psychiatrie-Kandidat vor Ort, Sachverst\xe4ndiger in unserem Zentrum, vertrauensw\xfcrdiger Arzt und vertrauensw\xfcrdiger Arzt Reparatur Vor Kurzem wurde in einer Woche ein weiterer Beitrag zum Thema geleistet: \u201eDie psychiatrische Analyse wurde innerhalb weniger Tage in den Vereinigten Staaten durchgef\xfchrt , \u0441\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u0438\u0439 \u0442\u0430 \u201eIndividuelles Problem\u201c.",text2UA:"",text2EN:"",text2DE:"",image1:a,image2:"",image3:t,image4:"",image5:"",date:"01.06.2024"},{id:"bnrleqdyha",titleUA:"\u041f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u043d\u044f \u043c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c\u0443 \u043f\u0440\u043e \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u044e \u0442\u0430 \u0432\u0437\u0430\u0454\u043c\u043e\u0434\u0456\u044e \u043c\u0456\u0436 \u043f\u043e\u043b\u044c\u0441\u044c\u043a\u043e\u044e \u043a\u043e\u043c\u043f\u0430\u043d\u0456\u0454\u044e Monta Materials Handling sp. z. o.o., \u0413\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u043e\u044e \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u0454\u044e \xab\u0412\u0441\u0435\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0430 \u0430\u0441\u043e\u0446\u0456\u0430\u0446\u0456\u044f \u0433\u0435\u043c\u043e\u043a\u043e\u0440\u0435\u043a\u0446\u0456\u0457 \u0442\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457\xbb \u0442\u0430 \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0410\u0423\u0420\u0423\u041c",titleEN:"Signing of a memorandum of cooperation and interaction between the Polish company Monta Materials Handling sp. z. o.o., the Public Organization \xabAll-Ukrainian Association of Hemocorrection and Rehabilitation\xbb and the AURUM Rehabilitation Center",titleDE:"Unterzeichnung eines Memorandums \xfcber Zusammenarbeit und Interaktion zwischen dem polnischen Unternehmen Monta Materials Handling sp. z. o.o., \xf6ffentliche Organisation \u201eAllukrainische Vereinigung f\xfcr H\xe4mokorrektur und Rehabilitation\u201c und Rehabilitationszentrum AURUM",text1UA:"26 \u0441\u0456\u0447\u043d\u044f 2024 \u0440\u043e\u043a\u0443 \u0431\u0443\u043b\u043e \u043f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u043e \u041c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c \u043f\u0440\u043e \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u044e \u0442\u0430 \u0432\u0437\u0430\u0454\u043c\u043e\u0434\u0456\u044e \u043c\u0456\u0436 \u043f\u043e\u043b\u044c\u0441\u044c\u043a\u043e\u044e \u043a\u043e\u043c\u043f\u0430\u043d\u0456\u0454\u044e Monta Materials Handling sp. z. o.o., \u0413\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u043e\u044e \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u0454\u044e \xab\u0412\u0441\u0435\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0430 \u0430\u0441\u043e\u0446\u0456\u0430\u0446\u0456\u044f \u0433\u0435\u043c\u043e\u043a\u043e\u0440\u0435\u043a\u0446\u0456\u0457 \u0442\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457\xbb \u0442\u0430 \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0410\u0423\u0420\u0423\u041c.",text1EN:"On January 26, 2024, a Memorandum of Cooperation and Interaction was signed between the Polish company Monta Materials Handling sp. z. o.o., the Public Organization \xabAll-Ukrainian Association of Hemocorrection and Rehabilitation\xbb and the AURUM Rehabilitation Center.",text1DE:"Am 26. Januar 2024 wurde ein Memorandum \xfcber Zusammenarbeit und Interaktion zwischen dem polnischen Unternehmen Monta Materials Handling sp. unterzeichnet. z. o.o., die \xf6ffentliche Organisation \u201eAllukrainische Vereinigung f\xfcr H\xe4mokorrektur und Rehabilitation\u201c und das Rehabilitationszentrum AURUM.",text2UA:"\u041e\u0441\u043d\u043e\u0432\u043d\u0430 \u043c\u0435\u0442\u0430 \u0443\u043a\u043b\u0430\u0434\u0430\u043d\u043d\u044f \u041c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c\u0443 \u2013 \u0446\u0435  \u0441\u043f\u0440\u0438\u044f\u043d\u043d\u044f \u043f\u043e\u0440\u0430\u043d\u0435\u043d\u0438\u043c \u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0438\u043c \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u0438\u043c \u0442\u0430 \u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0438\u043c \u0432\u0435\u0442\u0435\u0440\u0430\u043d\u0430\u043c \u0443 \u0434\u043e\u0441\u044f\u0433\u043d\u0435\u043d\u043d\u0456 \u0443\u0441\u043f\u0456\u0445\u0443 \u043f\u0456\u0441\u043b\u044f \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u043e\u0457 \u0441\u043b\u0443\u0436\u0431\u0438, \u0437\u0430\u0441\u0442\u043e\u0441\u043e\u0432\u0443\u044e\u0447\u0438 \u0456\u043d\u0434\u0438\u0432\u0456\u0434\u0443\u0430\u043b\u044c\u043d\u0438\u0439 \u043f\u0456\u0434\u0445\u0456\u0434 \u0434\u043e \u043f\u043e\u0442\u0440\u0435\u0431 \u043a\u043e\u0436\u043d\u043e\u0433\u043e; \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457 \u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0438\u0445 \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u0438\u0445 \u0432\u0435\u0442\u0435\u0440\u0430\u043d\u0456\u0432, \u044f\u043a\u0456 \u0431\u0440\u0430\u043b\u0438 \u0443\u0447\u0430\u0441\u0442\u044c \u0443 \u0431\u043e\u0439\u043e\u0432\u0438\u0445 \u0434\u0456\u044f\u0445; \u0437\u0430\u0431\u0435\u0437\u043f\u0435\u0447\u0435\u043d\u043d\u044f \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c\u0438, \u043f\u0456\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0442\u0430 \u043f\u0440\u043e\u0441\u0443\u0432\u0430\u043d\u043d\u044f \u0443\u0441\u043f\u0456\u0448\u043d\u043e\u0457 \u0430\u0434\u0430\u043f\u0442\u0430\u0446\u0456\u0457 \u0437\u0430\u0445\u0438\u0441\u043d\u0438\u043a\u0456\u0432 \u0423\u043a\u0440\u0430\u0457\u043d\u0438 \u0434\u043e \u0446\u0438\u0432\u0456\u043b\u044c\u043d\u043e\u0433\u043e \u0436\u0438\u0442\u0442\u044f. \u0412 \u0440\u0430\u043c\u043a\u0430\u0445 \u0446\u0456\u0454\u0457 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 2024 \u0440\u043e\u043a\u0443 \u0431\u0443\u043b\u043e \u043f\u0440\u043e\u0444\u0456\u043d\u0430\u043d\u0441\u043e\u0432\u0430\u043d\u043e \u043b\u0456\u043a\u0443\u0432\u0430\u043b\u044c\u043d\u043e-\u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0456 \u0437\u0430\u0445\u043e\u0434\u0438 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0431\u043b\u0430\u0433\u043e\u0434\u0456\u0439\u043d\u043e\u0457 \u041f\u0440\u043e\u0433\u0440\u0430\u043c\u0438 \u0413\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u043e\u0457 \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u0457 \xab\u0412\u0441\u0435\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0430 \u0430\u0441\u043e\u0446\u0456\u0430\u0446\u0456\u044f \u0433\u0435\u043c\u043e\u043a\u043e\u0440\u0435\u043a\u0446\u0456\u0457 \u0442\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457\xbb \xab\u041a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u0430 \u043c\u0435\u0434\u0438\u043a\u043e-\u043f\u0441\u0438\u0445\u043e\u043b\u043e\u0433\u0456\u0447\u043d\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u044f \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u043e\u0441\u043b\u0443\u0436\u0431\u043e\u0432\u0446\u0456\u0432, \u044f\u043a\u0456 \u043f\u0440\u0438\u0439\u043c\u0430\u044e\u0442\u044c \u0431\u0435\u0437\u043f\u043e\u0441\u0435\u0440\u0435\u0434\u043d\u044e \u0443\u0447\u0430\u0441\u0442\u044c \u0443 \u0437\u0430\u0445\u043e\u0434\u0430\u0445, \u043d\u0435\u043e\u0431\u0445\u0456\u0434\u043d\u0438\u0445 \u0434\u043b\u044f \u0437\u0430\u0431\u0435\u0437\u043f\u0435\u0447\u0435\u043d\u043d\u044f \u043e\u0431\u043e\u0440\u043e\u043d\u0438 \u0423\u043a\u0440\u0430\u0457\u043d\u0438, \u0437\u0430\u0445\u0438\u0441\u0442\u0443 \u0431\u0435\u0437\u043f\u0435\u043a\u0438 \u043d\u0430\u0441\u0435\u043b\u0435\u043d\u043d\u044f \u0442\u0430 \u0456\u043d\u0442\u0435\u0440\u0435\u0441\u0456\u0432 \u0434\u0435\u0440\u0436\u0430\u0432\u0438 \u0443 \u0437\u0432\u2019\u044f\u0437\u043a\u0443 \u0437 \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u043e\u044e \u0430\u0433\u0440\u0435\u0441\u0456\u0454\u044e \u0440\u043e\u0441\u0456\u0439\u0441\u044c\u043a\u043e\u0457 \u0444\u0435\u0434\u0435\u0440\u0430\u0446\u0456\u0457 \u043f\u0440\u043e\u0442\u0438 \u0423\u043a\u0440\u0430\u0457\u043d\u0438 (\u0432 \u0440\u043e\u0441\u0456\u0439\u0441\u044c\u043a\u043e-\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0456\u0439 \u0432\u0456\u0439\u043d\u0456), \u0432\u0435\u0442\u0435\u0440\u0430\u043d\u0456\u0432 \u0440\u043e\u0441\u0456\u0439\u0441\u044c\u043a\u043e-\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u043e\u0457 \u0432\u0456\u0439\u043d\u0438 \u0442\u0430 \u0447\u043b\u0435\u043d\u0456\u0432 \u0457\u0445 \u0441\u0456\u043c\u0435\u0439\xbb \u043d\u0430 \u0437\u0430\u0433\u0430\u043b\u044c\u043d\u0443 \u0441\u0443\u043c\u0443 \u043f\u043e\u043d\u0430\u0434  3000 \u0454\u0432\u0440\u043e.",text2EN:"The main purpose of concluding the Memorandum is to assist wounded Ukrainian military personnel and Ukrainian veterans in achieving success after military service, applying an individual approach to the needs of each; rehabilitation of Ukrainian military veterans who participated in hostilities; provision of resources, training and promotion of the successful adaptation of Ukraine's defenders to civilian life. As part of this cooperation, during 2024, medical and rehabilitation measures were financed within the framework of the charitable Program of the Public Organization \xabAll-Ukrainian Association of Hemocorrection and Rehabilitation\xbb \xabComprehensive medical and psychological rehabilitation of military personnel who take a direct part in measures necessary to ensure the defense of Ukraine, protect the security of the population and the interests of the state in connection with the military aggression of the Russian Federation against Ukraine (in the Russian-Ukrainian war), veterans of the Russian-Ukrainian war and their family members\xbb for a total amount of over 3,000 euros.",text2DE:"Das Hauptziel des Abschlusses des Memorandums besteht darin, verwundeten ukrainischen Milit\xe4rangeh\xf6rigen und ukrainischen Veteranen dabei zu helfen, nach dem Milit\xe4rdienst erfolgreich zu sein, wobei ein individueller Ansatz auf die Bed\xfcrfnisse jedes Einzelnen angewendet wird. Rehabilitierung ukrainischer Kriegsveteranen, die an Feindseligkeiten teilgenommen haben; Bereitstellung von Ressourcen, Ausbildung und F\xf6rderung der erfolgreichen Eingliederung der ukrainischen Verteidiger in das zivile Leben. Im Rahmen dieser Zusammenarbeit wurden im Jahr 2024 medizinische und Rehabilitationsma\xdfnahmen im Rahmen des Wohlt\xe4tigkeitsprogramms der \xf6ffentlichen Organisation \u201eAllukrainische Vereinigung f\xfcr H\xe4mokorrektur und Rehabilitation\u201c finanziert. \u201eUmfassende medizinische und psychologische Rehabilitation von Milit\xe4rangeh\xf6rigen, die direkt an Aktivit\xe4ten, die zur Gew\xe4hrleistung der Verteidigung der Ukraine, zum Schutz der Sicherheit der Bev\xf6lkerung und der Interessen des Staates im Zusammenhang mit der milit\xe4rischen Aggression der Russischen F\xf6deration gegen die Ukraine (im russisch-ukrainischen Krieg) erforderlich sind, Veteranen des russisch-ukrainischen Krieges und ihre Familienangeh\xf6rige\u201c in einer Gesamth\xf6he von \xfcber 3.000 Euro.",image1:r,image2:o,image3:s,image4:"",image5:"",date:"26.01.2024"},{id:"vwreifxhad",titleUA:"23 \u0433\u0440\u0443\u0434\u043d\u044f \xa02023 \u0440\u043e\u043a\u0443 \u0432 \u0442\u0435\u0430\u0442\u0440\u0456 \xab\u0421\u0443\u0437\u0456\u0440\u2019\u044f\xbb \u0432\u0456\u0434\u0431\u0443\u0432\u0441\u044f \u0431\u043b\u0430\u0433\u043e\u0434\u0456\u0439\u043d\u0438\u0439 \u0430\u0443\u043a\u0446\u0456\u043e\u043d \u0432 \u043f\u0456\u0434\u0442\u0440\u0438\u043c\u043a\u0443 \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u043e\u0433\u043e \u0426\u0435\u043d\u0442\u0440\u0443 \xab\u0410\u0443\u0440\u0443\u043c\xbb, \u0432 \u044f\u043a\u043e\u043c\u0443 \u0432\u0437\u044f\u043b\u0438 \u0443\u0447\u0430\u0441\u0442\u044c \u0410\u0434\u0430 \u0420\u043e\u0433\u043e\u0432\u0446\u0435\u0432\u0430 \u0442\u0430 \u041e\u043b\u0435\u0433 \u0421\u043a\u0440\u0438\u043f\u043a\u0430.",titleEN:"On December 23, 2023, a charity auction was held at the \xabSuzir'ya\xbb Theater in support of the \xabAurum\xbb Rehabilitation Center, in which Ada Rogovtseva and Oleg Skrypka participated.",titleDE:"Am 23. Dezember 2023 fand im Theater \u201eSuzir'ya\u201c eine Wohlt\xe4tigkeitsauktion zugunsten des Rehabilitationszentrums \u201eAurum\u201c statt, an der Ada Rogovtseva und Oleg Skrypka teilnahmen.",text1UA:"23 \u0433\u0440\u0443\u0434\u043d\u044f \xa02023 \u0440\u043e\u043a\u0443 \u0432 \u0442\u0435\u0430\u0442\u0440\u0456 \xab\u0421\u0443\u0437\u0456\u0440\u2019\u044f\xbb \u0432\u0456\u0434\u0431\u0443\u0432\u0441\u044f \u0431\u043b\u0430\u0433\u043e\u0434\u0456\u0439\u043d\u0438\u0439 \u0430\u0443\u043a\u0446\u0456\u043e\u043d \u0432 \u043f\u0456\u0434\u0442\u0440\u0438\u043c\u043a\u0443 \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u043e\u0433\u043e \u0426\u0435\u043d\u0442\u0440\u0443 \xab\u0410\u0443\u0440\u0443\u043c\xbb, \u0432 \u044f\u043a\u043e\u043c\u0443 \u0432\u0437\u044f\u043b\u0438 \u0443\u0447\u0430\u0441\u0442\u044c \u0410\u0434\u0430 \u0420\u043e\u0433\u043e\u0432\u0446\u0435\u0432\u0430 \u0442\u0430 \u041e\u043b\u0435\u0433 \u0421\u043a\u0440\u0438\u043f\u043a\u0430.",text1EN:"On December 23, 2023, a charity auction was held at the \xabSuzir'ya\xbb Theater in support of the \xabAurum\xbb Rehabilitation Center, in which Ada Rogovtseva and Oleg Skrypka participated.",text1DE:"Am 23. Dezember 2023 fand im Theater \u201eSuzir'ya\u201c eine Wohlt\xe4tigkeitsauktion zugunsten des Rehabilitationszentrums \u201eAurum\u201c statt, an der Ada Rogovtseva und Oleg Skrypka teilnahmen.",text2UA:"",text2EN:"",text2DE:"",image1:n.p+"static/media/vwreifxhad_3.b904ebd8c7f0b9d781c1.webp",image2:"",image3:c,image4:n.p+"static/media/vwreifxhad_4.003a8b0498c40707c556.webp",image5:"",date:"23.12.2023"},{id:"pkmsvzutgf",titleUA:"\u041f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u043e \u041c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c \u043f\u0440\u043e \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u044e \u0442\u0430 \u0432\u0437\u0430\u0454\u043c\u043e\u0434\u0456\u044e \u043c\u0456\u0436 \u041a\u0438\u0457\u0432\u0441\u044c\u043a\u0438\u043c  \u043e\u0431\u043b\u0430\u0441\u043d\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0438 \u0437\u0430\u0445\u0438\u0441\u043d\u0438\u043a\u0430\u043c \u0423\u043a\u0440\u0430\u0457\u043d\u0438 \u0456\u043c\u0435\u043d\u0456 \u0411\u0430\u0440\u0430\u043d\u043e\u0432\u0430 \u0412\u0456\u0442\u0430\u043b\u0456\u044f \u0410\u043d\u0430\u0442\u043e\u043b\u044c\u043e\u0432\u0438\u0447\u0430 \u043f\u0440\u0438 \u041a\u0438\u0457\u0432\u0441\u044c\u043a\u0456\u0439 \u043e\u0431\u043b\u0430\u0441\u043d\u0456\u0439 \u0440\u0430\u0434\u0456, \u0413\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u043e\u044e \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u0454\u044e \xab\u0412\u0441\u0435\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0430 \u0430\u0441\u043e\u0446\u0456\u0430\u0446\u0456\u044f \u0433\u0435\u043c\u043e\u043a\u043e\u0440\u0435\u043a\u0446\u0456\u0457 \u0442\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457\xbb \u0442\u0430 \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0410\u0423\u0420\u0423\u041c",titleEN:"A Memorandum of Cooperation and Interaction was signed between the Kyiv Regional Center for Assistance to Defenders of Ukraine named after Vitaliy Anatolyovych Baranov under the Kyiv Regional Council, the Public Organization \xabAll-Ukrainian Association of Hemocorrection and Rehabilitation\xbb and the AURUM Rehabilitation Center",titleDE:"Zwischen dem nach Vitali Anatolyovych Baranov benannten regionalen Zentrum f\xfcr Hilfe f\xfcr Verteidiger der Ukraine in Kiew beim regionalen Rat von Kiew, der \xf6ffentlichen Organisation \u201eAllukrainische Vereinigung f\xfcr H\xe4mokorrektur und Rehabilitation\u201c und dem Rehabilitationszentrum AURUM wurde ein Memorandum \xfcber Zusammenarbeit und Interaktion unterzeichnet.",text1UA:"02 \u0436\u043e\u0432\u0442\u043d\u044f 2023 \u0440\u043e\u043a\u0443 \u0431\u0443\u043b\u043e \u043f\u0456\u0434\u043f\u0438\u0441\u0430\u043d\u043e \u041c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c \u043f\u0440\u043e \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u044e \u0442\u0430 \u0432\u0437\u0430\u0454\u043c\u043e\u0434\u0456\u044e \u043c\u0456\u0436 \u041a\u0438\u0457\u0432\u0441\u044c\u043a\u0438\u043c  \u043e\u0431\u043b\u0430\u0441\u043d\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0438 \u0437\u0430\u0445\u0438\u0441\u043d\u0438\u043a\u0430\u043c \u0423\u043a\u0440\u0430\u0457\u043d\u0438 \u0456\u043c\u0435\u043d\u0456 \u0411\u0430\u0440\u0430\u043d\u043e\u0432\u0430 \u0412\u0456\u0442\u0430\u043b\u0456\u044f \u0410\u043d\u0430\u0442\u043e\u043b\u044c\u043e\u0432\u0438\u0447\u0430 \u043f\u0440\u0438 \u041a\u0438\u0457\u0432\u0441\u044c\u043a\u0456\u0439 \u043e\u0431\u043b\u0430\u0441\u043d\u0456\u0439 \u0440\u0430\u0434\u0456, \u0413\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u043e\u044e \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u0454\u044e \xab\u0412\u0441\u0435\u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0430 \u0430\u0441\u043e\u0446\u0456\u0430\u0446\u0456\u044f \u0433\u0435\u043c\u043e\u043a\u043e\u0440\u0435\u043a\u0446\u0456\u0457 \u0442\u0430 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457\xbb \u0442\u0430   \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u043c \u0446\u0435\u043d\u0442\u0440\u043e\u043c \u0410\u0423\u0420\u0423\u041c.",text1EN:"On October 2, 2023, a Memorandum of Cooperation and Interaction was signed between the Kyiv Regional Center for Assistance to Defenders of Ukraine named after Vitaliy Anatolyovych Baranov under the Kyiv Regional Council, the Public Organization \xabAll-Ukrainian Association of Hemocorrection and Rehabilitation\xbb and the AURUM Rehabilitation Center.",text1DE:"Am 2. Oktober 2023 wurde ein Memorandum \xfcber Zusammenarbeit und Interaktion zwischen dem nach Vitali Anatolyovych Baranov benannten regionalen Zentrum f\xfcr Hilfe f\xfcr Verteidiger der Ukraine in Kiew beim regionalen Rat von Kiew, der \xf6ffentlichen Organisation \u201eAllukrainische Vereinigung f\xfcr H\xe4mokorrektur und Rehabilitation\u201c und das AURUM Rehabilitationszentrum.",text2UA:"\u0417\u0430\u0432\u0434\u0430\u043d\u043d\u044f\u043c\u0438 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0443\u043a\u043b\u0430\u0434\u0435\u043d\u043e\u0433\u043e \u041c\u0435\u043c\u043e\u0440\u0430\u043d\u0434\u0443\u043c\u0443 \u0454 \u0441\u043f\u0456\u043b\u044c\u043d\u0430 \u0434\u0456\u044f\u043b\u044c\u043d\u0456\u0441\u0442\u044c \u0443 \u043d\u0430\u043f\u0440\u044f\u043c\u0430\u0445: \u041f\u0441\u0438\u0445\u043e\u0444\u0456\u0437\u0438\u0447\u043d\u043e\u0457 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457 \u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0438\u0445 \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u0438\u0445 \u0432\u0435\u0442\u0435\u0440\u0430\u043d\u0456\u0432, \u044f\u043a\u0456 \u0431\u0440\u0430\u043b\u0438 \u0443\u0447\u0430\u0441\u0442\u044c \u0443 \u0431\u043e\u0439\u043e\u0432\u0438\u0445 \u0434\u0456\u044f\u0445; \u0443\u0437\u0433\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043f\u043e\u0437\u0438\u0446\u0456\u0439, \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u044f \u0442\u0430 \u0440\u0435\u0430\u043b\u0456\u0437\u0430\u0446\u0456\u044f \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0437\u0430\u0445\u043e\u0434\u0456\u0432 \u0449\u043e\u0434\u043e \u0441\u043f\u0440\u0438\u044f\u043d\u043d\u044f \u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u0438\u043c \u0432\u0435\u0442\u0435\u0440\u0430\u043d\u0430\u043c \u0443 \u0434\u043e\u0441\u044f\u0433\u043d\u0435\u043d\u043d\u0456 \u0443\u0441\u043f\u0456\u0445\u0443 \u043f\u0456\u0441\u043b\u044f \u0432\u0456\u0439\u0441\u044c\u043a\u043e\u0432\u043e\u0457 \u0441\u043b\u0443\u0436\u0431\u0438, \u0437\u0430\u0431\u0435\u0437\u043f\u0435\u0447\u0435\u043d\u043d\u044f \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c\u0438, \u043f\u0456\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0442\u0430 \u043f\u0440\u043e\u0441\u0443\u0432\u0430\u043d\u043d\u044f \u0443\u0441\u043f\u0456\u0448\u043d\u043e\u0457 \u0430\u0434\u0430\u043f\u0442\u0430\u0446\u0456\u0457 \u0437\u0430\u0445\u0438\u0441\u043d\u0438\u043a\u0456\u0432 \u0423\u043a\u0440\u0430\u0457\u043d\u0438; \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u044f \u0456 \u043f\u0440\u043e\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0437\u0430\u0445\u043e\u0434\u0456\u0432 (\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u043d\u0438\u0445 \u0437\u0443\u0441\u0442\u0440\u0456\u0447\u0435\u0439, \u043a\u0440\u0443\u0433\u043b\u0438\u0445 \u0441\u0442\u043e\u043b\u0456\u0432, \u0442\u0435\u043c\u0430\u0442\u0438\u0447\u043d\u0438\u0445 \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u0430\u0445 \u0456 \u043f\u0440\u043e\u0435\u043a\u0442\u0456\u0432), \u0437\u0430\u043b\u0443\u0447\u0435\u043d\u043d\u044f \u0456\u043d\u0448\u0438\u0445 \u0437\u0430\u0456\u043d\u0442\u0435\u0440\u0435\u0441\u043e\u0432\u0430\u043d\u0438\u0445 \u0441\u0442\u043e\u0440\u0456\u043d, \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u043f\u043b\u0430\u043d\u0456\u0432 \u0440\u043e\u0431\u043e\u0442\u0438 \u0442\u043e\u0449\u043e. \u041f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 2024 \u0440\u043e\u043a\u0443 \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u0432\u0438\u0449\u0435\u0432\u043a\u0430\u0437\u0430\u043d\u043e\u0457 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456 \u043f\u0440\u043e\u0439\u0448\u043b\u0438 \u043b\u0456\u043a\u0443\u0432\u0430\u043b\u044c\u043d\u043e-\u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u0439 \u043a\u0443\u0440\u0441 10 \u0437\u0430\u0445\u0438\u0441\u043d\u0438\u043a\u0456\u0432, \u043e\u0434\u0438\u043d \u0437 \u043d\u0438\u0445 - \u0442\u0440\u0438 \u043a\u0443\u0440\u0441\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u043e.",text2EN:"The objectives of cooperation within the framework of the concluded Memorandum are joint activities in the following areas: Psychophysical rehabilitation of Ukrainian military veterans who participated in hostilities; coordination of positions, organization and implementation of joint activities to assist Ukrainian veterans in achieving success after military service, provision of resources, preparation and promotion of successful adaptation of defenders of Ukraine; organization and holding of joint events (thematic meetings, round tables, thematic programs and projects), involvement of other interested parties, creation of joint work plans, etc. During 2024, within the framework of the above cooperation, 10 defenders underwent a medical and rehabilitation course, one of them - three courses repeatedly.",text2DE:"Die Ziele der Zusammenarbeit im Rahmen des abgeschlossenen Memorandums sind gemeinsame Aktivit\xe4ten in folgenden Bereichen: Psychophysische Rehabilitation ukrainischer Milit\xe4rveteranen, die an Feindseligkeiten teilgenommen haben; Koordinierung der Positionen, Organisation und Durchf\xfchrung gemeinsamer Aktivit\xe4ten zur Unterst\xfctzung ukrainischer Veteranen beim Erreichen des Erfolgs nach dem Milit\xe4rdienst, Bereitstellung von Ressourcen, Ausbildung und F\xf6rderung einer erfolgreichen Anpassung der Verteidiger der Ukraine; Organisation und Durchf\xfchrung gemeinsamer Veranstaltungen (thematische Treffen, runde Tische, thematische Programme und Projekte), Einbeziehung weiterer Interessengruppen, Erstellung gemeinsamer Arbeitspl\xe4ne usw. Im Jahr 2024 haben im Rahmen der oben genannten Zusammenarbeit 10 Verteidiger einen Behandlungs- und Rehabilitationskurs absolviert, einer von ihnen sogar drei Kurse wiederholt.",image1:d,image2:"",image3:"",image4:"",image5:"",date:"02.10.2023"},{id:"qwoeijxhcd",titleUA:"\u0423\u043a\u043b\u0430\u0434\u0435\u043d\u0430 \u0423\u0433\u043e\u0434\u0430 \u043f\u0440\u043e \u043c\u0456\u0436\u043d\u0430\u0440\u043e\u0434\u043d\u0435 \u0441\u043f\u0456\u0432\u0440\u043e\u0431\u0456\u0442\u043d\u0438\u0446\u0442\u0432\u043e \u043c\u0456\u0436 Parzival Zentrum \u0442\u0430  \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u0438\u043c \u0426\u0435\u043d\u0442\u0440\u043e\u043c \u0410\u0423\u0420\u0423\u041c",titleEN:"An Agreement on International Cooperation has been concluded between Parzival Zentrum and the AURUM Rehabilitation Center",titleDE:"Zwischen dem Parzival Zentrum und dem AURUM Rehabilitationszentrum wurde eine Vereinbarung \xfcber internationale Zusammenarbeit geschlossen",text1UA:"10 \u0447\u0435\u0440\u0432\u043d\u044f 2023 \u0440\u043e\u043a\u0443 \u0431\u0443\u043b\u0430 \u0443\u043a\u043b\u0430\u0434\u0435\u043d\u0430 \u0423\u0433\u043e\u0434\u0430 \u043f\u0440\u043e \u043c\u0456\u0436\u043d\u0430\u0440\u043e\u0434\u043d\u0435 \u0441\u043f\u0456\u0432\u0440\u043e\u0431\u0456\u0442\u043d\u0438\u0446\u0442\u0432\u043e \u043c\u0456\u0436 Parzival Zentrum \u0442\u0430 \u0413\u0440\u043e\u043c\u0430\u0434\u0441\u044c\u043a\u0430 \u043e\u0440\u0433\u0430\u043d\u0456\u0437\u0430\u0446\u0456\u044f \xab\u0412\u0421\u0415\u0423\u041a\u0420\u0410\u0407\u041d\u0421\u042c\u041a\u0410 \u0410\u0421\u041e\u0426\u0406\u0410\u0426\u0406\u042f \u0413\u0415\u041c\u041e\u041a\u041e\u0420\u0415\u041a\u0426\u0406\u0407 \u0422\u0410 \u0420\u0415\u0410\u0411\u0406\u041b\u0406\u0422\u0410\u0426\u0406\u0407\xbb \u0423\u043a\u043b\u0430\u0434\u0435\u043d\u043d\u044f\u043c \u0446\u0456\u0454\u0457 \u0423\u0433\u043e\u0434\u0430 \u0421\u0442\u043e\u0440\u043e\u043d\u0438 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u044e\u0442\u044c, \u0449\u043e \u0456\u043d\u0442\u0435\u0440\u0435\u0441\u0430\u043c \u043a\u043e\u0436\u043d\u043e\u0457 \u0437 \u043d\u0438\u0445 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454 \u0441\u043f\u0456\u043b\u044c\u043d\u0435 \u0456 \u0443\u0437\u0433\u043e\u0434\u0436\u0435\u043d\u0435 \u043c\u0456\u0436\u043d\u0430\u0440\u043e\u0434\u043d\u0435 \u0441\u043f\u0456\u0432\u0440\u043e\u0431\u0456\u0442\u043d\u0438\u0446\u0442\u0432\u043e \u0449\u043e\u0434\u043e \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u0456 \u0442\u0430 \u0440\u043e\u0437\u0432\u0438\u0442\u043a\u0443 \u0420\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0439\u043d\u043e\u0433\u043e \u0426\u0435\u043d\u0442\u0440\u0443 \u0410\u0423\u0420\u0423\u041c \u0432 \u043d\u0430\u043f\u0440\u044f\u043c\u043a\u0443 \u0434\u043e\u043f\u043e\u043c\u043e\u0433\u0438 \u0434\u0456\u0442\u044f\u043c \u0442\u0430 \u043c\u043e\u043b\u043e\u0434\u0456, \u044f\u043a\u0456 \u043f\u043e\u0441\u0442\u0440\u0430\u0436\u0434\u0430\u043b\u0438 \u0432\u0456\u0434 \u0432\u0456\u0439\u043d\u0438 \u0432 \u0423\u043a\u0440\u0430\u0457\u043d\u0456.",text1EN:"On June 10, 2023, an Agreement on International Cooperation was concluded between Parzival Zentrum and the Public Organization \xabALL-UKRAINIAN ASSOCIATION OF HEMOCORRECTION AND REHABILITATION\xbb. By concluding this Agreement, the Parties confirm that joint and coordinated international cooperation on cooperation and development of the AURUM Rehabilitation Center in the direction of helping children and youth affected by the war in Ukraine is in the interests of each of them.",text1DE:"Am 10. Juni 2023 wurde zwischen dem Parzival Zentrum und der \xf6ffentlichen Organisation \u201eALLUKRAINISCHER VERBAND F\xdcR H\xc4MOKORREKTUR UND REHABILITATION\u201c eine Vereinbarung \xfcber internationale Zusammenarbeit geschlossen. Mit dem Abschluss dieser Vereinbarung best\xe4tigen die Parteien, dass eine gemeinsame und koordinierte internationale Zusammenarbeit bei der Zusammenarbeit und Entwicklung von Die Hilfeleistung des AURUM-Rehabilitationszentrums liegt im Interesse jedes einzelnen vom Krieg in der Ukraine betroffenen Kindes und Jugendlichen.",text2UA:"Parzival Zentrum \u0432 \u041a\u0430\u0440\u043b\u0441\u0440\u0443\u0435, \u041d\u0456\u043c\u0435\u0447\u0447\u0438\u043d\u0430  \u043c\u0430\u0454  25 \u0440\u043e\u043a\u0456\u0432 \u0443\u0441\u043f\u0456\u0448\u043d\u043e\u0457 \u0440\u043e\u0431\u043e\u0442\u0438 \u0437 \u0431\u0456\u0436\u0435\u043d\u0446\u044f\u043c\u0438 \u0442\u0430  \u0434\u0456\u0442\u044c\u043c\u0438 \u0437 \u0443\u0441\u044c\u043e\u0433\u043e \u0441\u0432\u0456\u0442\u0443, \u044f\u043a\u0456 \u0437\u0430\u0437\u043d\u0430\u043b\u0438 \u0442\u0440\u0430\u0432\u043c\u0443\u0432\u0430\u043d\u043d\u044f \u0432 \u043d\u0430\u0441\u043b\u0456\u0434\u043e\u043a \u0432\u0456\u0439\u043d\u0438, \u043d\u0430\u0441\u0438\u043b\u044c\u0441\u0442\u0432\u0430 \u0442\u0430 \u0433\u043e\u043b\u043e\u0434\u0443. \u041c\u0456\u0436\u043d\u0430\u0440\u043e\u0434\u043d\u0430 \u0441\u043f\u0456\u0432\u043f\u0440\u0430\u0446\u044f \u0437 Parzival Zentrum -\u0446\u0435 \u043c\u043e\u0436\u043b\u0438\u0432\u0456\u0441\u0442\u044c \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u043d\u044f \u043d\u043e\u0432\u0438\u0445 \u0444\u043e\u0440\u043c\u0430\u0442\u0456\u0432 \u0442\u0435\u0440\u0430\u043f\u0435\u0432\u0442\u0438\u0447\u043d\u043e\u0433\u043e \u043c\u0435\u0434\u0438\u043a\u043e-\u043f\u0435\u0434\u0430\u0433\u043e\u0433\u0456\u0447\u043d\u043e\u0433\u043e \u0432\u0442\u0440\u0443\u0447\u0430\u043d\u043d\u044f \u0432 \u0441\u0438\u0441\u0442\u0435\u043c\u0456 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u043d\u043e \u0432\u0438\u043c\u043e\u0433 \u0436\u0438\u0442\u0442\u044f \u0432 \u0441\u0443\u0447\u0430\u0441\u043d\u043e\u043c\u0443 \u0441\u0432\u0456\u0442\u0456. \u041d\u0430 \u0441\u0430\u043c \u043f\u0435\u0440\u0435\u0434 \u2013 \u0446\u0435  \u043e\u0431\u043c\u0456\u043d \u0434\u043e\u0441\u0432\u0456\u0434\u043e\u043c \u0437 \u043c\u0435\u0442\u043e\u044e \u0440\u043e\u0437\u0432\u0438\u0442\u043a\u0443 \u0441\u0438\u0441\u0442\u0435\u043c\u0438 \u043f\u0441\u0438\u0445\u043e\u0444\u0456\u0437\u0438\u0447\u043d\u043e\u0457 \u0440\u0435\u0430\u0431\u0456\u043b\u0456\u0442\u0430\u0446\u0456\u0457 \u0432 \u0423\u043a\u0440\u0430\u0457\u043d\u0456 \u0442\u0430 \u0432\u043f\u0440\u043e\u0432\u0430\u0434\u0436\u0435\u043d\u043d\u044f \u0443\u043d\u0456\u043a\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0443\u043a\u0440\u0430\u0457\u043d\u0441\u044c\u043a\u043e\u0433\u043e \u0434\u043e\u0441\u0432\u0456\u0434\u0443 \u0432 \u043f\u043e\u0454\u0434\u043d\u0430\u043d\u043d\u0456 \u0437 \u0454\u0432\u0440\u043e\u043f\u0435\u0439\u0441\u044c\u043a\u0438\u043c\u0438 \u043c\u0435\u0442\u043e\u0434\u0438\u043a\u0430\u043c\u0438 \u0437\u0430 \u043c\u0435\u0436\u0430\u043c\u0438 \u0423\u043a\u0440\u0430\u0457\u043d\u0456, \u0432 \u0404\u0432\u0440\u043e\u043f\u0456 \u0442\u0430 \u0432 \u0443\u0441\u044c\u043e\u043c\u0443  \u0441\u0432\u0456\u0442\u0456.",text2EN:"Parzival Zentrum in Karlsruhe, Germany has 25 years of successful work with refugees and children from all over the world who have been traumatized by war, violence and hunger. International cooperation with Parzival Zentrum is an opportunity to create new formats of therapeutic medical and pedagogical intervention in the rehabilitation system in accordance with the requirements of life in the modern world. First of all, it is an exchange of experience with the aim of developing the psychophysical rehabilitation system in Ukraine and implementing the unique Ukrainian experience in combination with European methods outside Ukraine, in Europe and around the world.",text2DE:"Das Parzival Zentrum in Karlsruhe arbeitet seit 25 Jahren erfolgreich mit Fl\xfcchtlingen und Kindern aus aller Welt, die durch Krieg, Gewalt und Hunger traumatisiert sind. Die internationale Zusammenarbeit mit dem Parzival Zentrum ist eine Chance, neue Formate therapeutischer, medizinischer und p\xe4dagogischer Interventionen im Rehabilitationssystem entsprechend den Anforderungen des Lebens in der modernen Welt zu schaffen. In erster Linie handelt es sich um einen Erfahrungsaustausch mit dem Ziel, das System der psychophysischen Rehabilitation in der Ukraine weiterzuentwickeln und einzigartige ukrainische Erfahrungen in Kombination mit europ\xe4ischen Methoden au\xdferhalb der Ukraine, in Europa und der ganzen Welt einzuf\xfchren.",image1:h,image2:u,image3:m,image4:l,image5:"",date:"10.06.2023"}]},7488:(e,i,n)=>{n.d(i,{A:()=>o});var a=n(5043),t=n(9634),r=(n(1580),n(579));const o=e=>{let{src:i,alt:n,className:o}=e;const[s,d]=(0,a.useState)(!1);return(0,r.jsx)(t.LazyLoadImage,{src:i,alt:n,className:o,onLoad:()=>d(!0),style:{opacity:s?1:0,transition:"opacity 0.3s ease-in-out"},wrapperProps:{style:{display:"block"}}})}},9628:(e,i,n)=>{n.d(i,{A:()=>r});var a=n(4117),t=n(579);const r=()=>{const{i18n:e}=(0,a.Bd)(),i=e.language,n={en:"".concat("/faurum","/logo-en.png"),de:"".concat("/faurum","/logo-de.png"),ua:"".concat("/faurum","/logo-ua.png")},r={en:"AURUM",de:"AURUM",ua:"\u0410\u0423\u0420\u0423\u041c"};return[(0,t.jsx)("meta",{property:"og:image",content:n[i]||n.ua},"og:image"),(0,t.jsx)("meta",{property:"og:image:width",content:"1200"},"og:image:width"),(0,t.jsx)("meta",{property:"og:image:height",content:"630"},"og:image:height"),(0,t.jsx)("meta",{property:"og:site_name",content:r[i]||r.ua},"og:site_name")]}}}]);
